import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { checkout } from "../src/checkout.js";
import { _reset, _setLatency, _stock } from "../src/inventory.js";

beforeEach(() => _reset());

test("checkout reserves every item", async () => {
  const order = await checkout({ id: 1, items: [{ sku: "sku-red-mug", qty: 1 }] });
  assert.equal(order.reservations.length, 1);
  assert.equal(_stock("sku-red-mug"), 2);
});

test("checkout waits for slow reservations", async () => {
  _setLatency(39);
  const order = await checkout({ id: 2, items: [{ sku: "sku-red-mug", qty: 2 }] });
  assert.deepEqual(order.reservations.map((r) => r.sku), ["sku-red-mug"]);
  assert.equal(_stock("sku-red-mug"), 1);
});

test("checkout rejects an out-of-stock item", async () => {
  await assert.rejects(
    checkout({ id: 3, items: [{ sku: "sku-blue-mug", qty: 1 }] }),
    /out of stock: sku-blue-mug/,
  );
});

test("checkout releases partial reservations when one item fails", async () => {
  _setLatency(0);
  await assert.rejects(
    checkout({
      id: 4,
      items: [
        { sku: "sku-red-mug", qty: 2 },
        { sku: "sku-blue-mug", qty: 1 },
      ],
    }),
    /out of stock: sku-blue-mug/,
  );
  assert.equal(_stock("sku-red-mug"), 3);
});

